function transferWithSig(
    address from,
    address to,
    uint256 amount,
    bytes32 r, bytes32 s, uint8 v
) external {
    bytes32 hash = keccak256(abi.encodePacked(from, to, amount));
    bytes32 ethSigned = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash));
    // VULNERABILITY: No nonce check, no usedSignatures mapping
    require(ecrecover(ethSigned, v, r, s) == from, "invalid sig");
    balances[from] -= amount;
    balances[to] += amount;
}

function claimAirdrop(
    address recipient,
    uint256 amount,
    uint256 nonce,
    uint8 v, bytes32 r, bytes32 s
) external {
    require(!usedNonces[recipient][nonce], "nonce used");
    usedNonces[recipient][nonce] = true;
    // VULNERABILITY: Missing address(this) and block.chainid in hash
    bytes32 message = keccak256(abi.encode(recipient, amount, nonce));
    require(ecrecover(message, v, r, s) == signer, "invalid sig");
    token.transfer(recipient, amount);
}

mapping(bytes32 => bool) public executedSigs;

function executeAction(bytes calldata action, bytes calldata sig) external {
    bytes32 sigHash = keccak256(sig);
    require(!executedSigs[sigHash], "sig executed");
    executedSigs[sigHash] = true; // Flawed replay prevention!

    (bytes32 r, bytes32 s, uint8 v) = splitSig(sig);
    // VULNERABILITY: Raw ecrecover does not enforce s <= secp256k1n / 2
    address signer = ecrecover(keccak256(action), v, r, s);
    require(signer == admin, "not admin");
    _doAction(action);
}

using ECDSA for bytes32;

mapping(address => uint256) public nonces;

function executeWithPermit(
    address owner,
    address spender,
    uint256 value,
    uint256 deadline,
    bytes calldata signature
) external {
    require(block.timestamp <= deadline, "expired");
    bytes32 structHash = keccak256(abi.encode(
        PERMIT_TYPEHASH,
        owner,
        spender,
        value,
        nonces[owner]++,
        deadline
    ));
    bytes32 digest = _hashTypedDataV4(structHash); // EIP-712 with chainId & address(this)
    // SAFE: ECDSA.recover prevents high-s malleability and returns address(0) on error
    require(digest.recover(signature) == owner, "invalid signature");
    _approve(owner, spender, value);
}

mapping(address => bool) public hasClaimed;

function claimWithVoucher(
    uint256 amount,
    bytes calldata voucherSig
) external {
    require(!hasClaimed[msg.sender], "already claimed");
    hasClaimed[msg.sender] = true; // State lock prevents replay
    bytes32 msgHash = keccak256(abi.encodePacked(address(this), block.chainid, msg.sender, amount));
    bytes32 ethHash = ECDSA.toEthSignedMessageHash(msgHash);
    require(ECDSA.recover(ethHash, voucherSig) == voucherIssuer, "bad voucher");
    token.transfer(msg.sender, amount);
}

function verifySigner(address signer, bytes32 hash, bytes memory signature) internal view returns (bool) {
    if (signer.code.length > 0) {
        // EIP-1271 smart contract wallet (e.g. Gnosis Safe)
        return IERC1271(signer).isValidSignature(hash, signature) == 0x1626ba7e;
    } else {
        return ECDSA.recover(hash, signature) == signer;
    }
}

mapping(bytes32 => bool) public cancelledOrFilled;

function fillOrder(Order calldata order, bytes calldata signature) external {
    bytes32 orderHash = _hashOrder(order);
    require(!cancelledOrFilled[orderHash], "order already filled or cancelled");
    cancelledOrFilled[orderHash] = true; // One-time fulfillment gate
    require(ECDSA.recover(orderHash, signature) == order.maker, "invalid maker");
    _transferAssets(order);
}

function executeWithdraw(address to, uint256 amount, bytes calldata sig) external onlyOperator {
    bytes32 msgHash = keccak256(abi.encodePacked(to, amount));
    // Helper implementation not shown — may or may not check nonce
    require(_verifySignature(msgHash, sig), "signature failed");
    payable(to).transfer(amount);
}

function updateConfig(bytes calldata configData, uint256 nonce, bytes calldata sig) external withValidNonce(nonce) {
    bytes32 hash = keccak256(abi.encode(configData, nonce));
    require(ECDSA.recover(hash, sig) == admin);
    _applyConfig(configData);
}

function metaTransfer(address to, uint256 amount) external {
    // In ERC-2771, msg.sender is Forwarder; actual user is _msgSender()
    address sender = _msgSender();
    balances[sender] -= amount;
    balances[to] += amount;
}

function settleTrade(bytes calldata tradeData, bytes calldata sig) external {
    bool ok = IOracleValidator(validator).checkSignature(tradeData, sig);
    require(ok, "oracle sig invalid");
    _settle(tradeData);
}

mapping(address => uint256) public nonces;

function mintWithVoucher(
    uint256 amount,
    uint256 voucherId,
    bytes calldata sig
) external {
    // VULNERABILITY: Tracks caller nonce instead of voucherId uniqueness!
    require(nonces[msg.sender] == 0, "already minted");
    nonces[msg.sender] = 1;

    bytes32 hash = keccak256(abi.encodePacked(amount, voucherId));
    require(ECDSA.recover(hash, sig) == authority, "bad voucher");
    _mint(msg.sender, amount);
}

