address public emergencyAdmin; // Default uninitialized: address(0)

function emergencyShutdown(bytes32 hash, uint8 v, bytes32 r, bytes32 s) external {
    // VULNERABILITY: If signature is malformed, ecrecover returns address(0)
    // If emergencyAdmin is address(0), check succeeds!
    require(ecrecover(hash, v, r, s) == emergencyAdmin, "unauthorized");
    isShutdown = true;
}

function _domainSeparatorV4() internal view returns (bytes32) {
    if (block.chainid == _cachedChainId) {
        return _cachedDomainSeparator;
    }
    return _buildDomainSeparator(_TYPE_HASH, _HASHED_NAME, _HASHED_VERSION);
}

function verifyAggregated(bytes memory points) external view returns (bool) {
    // Calls BN256 pairing precompile at address(0x08)
    (bool ok, bytes memory result) = address(0x08).staticcall(points);
    require(ok && result.length > 0);
    return abi.decode(result, (uint256)) == 1;
}

function bridgeWithdraw(
    address recipient,
    uint256 amount,
    uint256 chainId, // Caller-supplied chainId parameter
    bytes calldata sig
) external {
    // Flawed check: validates that sig matches param, but doesn't check param against real chain!
    bytes32 hash = keccak256(abi.encodePacked(recipient, amount, chainId));
    require(ECDSA.recover(hash, sig) == bridgeValidator, "bad validator");
    // MISSING: require(chainId == block.chainid, "wrong chain");
    token.transfer(recipient, amount);
}
